create.example:
const guard = kcds.characters.Npc.create({
  soul: 'guard',
  name: 'Gate guard',
  nameplate: true,
  position: new kcds.math.Vector3(2340, 2070, 110),
});
guard.setNameplateText('Town guard');
guard.lookAt(player);
guard.say('Halt! Who goes there?');

create.exampleCs:
var guard = Npc.Create(new { soul = "guard", name = "Gate guard", nameplate = true, position = new Vector3(2340, 2070, 110) });
guard.SetNameplateText("Town guard");
guard.LookAt(player);
guard.Say("Halt! Who goes there?");

