getById.example:
kcds.core.Events.fromClient('npc:hail', (player, payload) => {
  const npc = kcds.characters.Npc.getById(Number(payload?.id));
  if (npc && npc.alive) {
    npc.lookAt(player);
  }
});

getById.exampleCs:
Events.FromClient("npc:hail", (Player player, JsValue payload) =>
{
    var npc = Npc.GetById(payload["id"].AsNumber());
    if (npc != null && npc.Alive)
    {
        npc.LookAt(player);
    }
});

