playAnimation.example:
guard.hold();
guard.playAnimation('Greetings', { tags: 'bowBig' });

kcds.core.Events.on('npcAnimationEnd', (npc, fragment, reason) => {
  if (npc !== guard) {
    return;
  }
  console.info(`${fragment} ended: ${reason}`);
  if (fragment === 'Greetings') {
    guard.playAnimation('', { clip: 'reading_stand_inv_in', loop: true });
  }
});

playAnimation.exampleCs:
guard.Hold();
guard.PlayAnimation("Greetings", new { tags = "bowBig" });

Events.On("npcAnimationEnd", (Npc npc, string fragment, JsValue reason) =>
{
    if (npc != guard)
    {
        return;
    }
    Log.Info($"{fragment} ended: {reason}");
    if (fragment == "Greetings")
    {
        guard.PlayAnimation("", new { clip = "reading_stand_inv_in", loop = true });
    }
});

adopt.example:
const { Npc } = kcds.characters;

const [first] = Npc.placements();
const gerta = first ? Npc.adopt(first.guid, { name: 'Gerta' }) : null;
if (gerta) {
  gerta.say('Good day.');
}

adopt.exampleCs:
var placements = Npc.Placements();
var gerta = placements.Length > 0 ? Npc.Adopt(placements[0]["guid"], new { name = "Gerta" }) : null;
if (gerta != null)
{
    gerta.Say("Good day.");
}

