placements.example:
const { Npc } = kcds.characters;

const smiths = Npc.placements().filter((row) => row.name.includes('smith'));
for (const row of smiths) {
  Npc.create({ soul: row.soul, position: row.position });
}

placements.exampleCs:
var smiths = Npc.Placements().Where(row => row["name"].Call("includes", "smith").AsBool()).ToArray();
foreach (var row in smiths)
{
    Npc.Create(new { soul = row["soul"], position = row["position"] });
}

lootOf.example:
const boar = kcds.characters.Npc.create({ position: { x: 1200, y: 800, z: 40 }, class: 'Boar' });
const loot = boar.lootOf();
if (loot) {
  console.info(loot.filter((row) => row.food).map((row) => row.name).join(', '));
}

lootOf.exampleCs:
var boar = Npc.Create(new Dictionary<string, object?> { ["position"] = new { x = 1200, y = 800, z = 40 }, ["class"] = "Boar" });
var loot = boar.LootOf();
if (loot)
{
    Log.Info(string.Join(", ", loot.Where(row => row["food"]).ToArray().Select(row => row["name"]).ToArray()));
}

